        value: this.stores.filter(s => s.status === 'approved').length,
        growth: growth * 0.5,
        spark
      }, {
        key: 'products',
        label: 'Total Active Products',
        value: this.priceRows.filter(p => p.status === 'active').length,
        growth: growth * 0.6,
        spark
